const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程：6x + 5 = 2x + 11' },
      { kind: 'text', payload: '① 移项' },
      { kind: 'text', payload: '6x − 2x = 11 − 5' },
      { kind: 'text', payload: '② 合并同类项' },
      { kind: 'text', payload: '4x = 6' },
      { kind: 'text', payload: '③ 系数化为 1' },
      { kind: 'text', payload: 'x = 6/4 = 3/2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    function rr(x, y, w, h, rad) {
      return [
        ['M', x + rad, y],
        ['L', x + w - rad, y],
        ['Q', x + w, y, x + w, y + rad],
        ['L', x + w, y + h - rad],
        ['Q', x + w, y + h, x + w - rad, y + h],
        ['L', x + rad, y + h],
        ['Q', x, y + h, x, y + h - rad],
        ['L', x, y + rad],
        ['Q', x, y, x + rad, y],
        ['Z']
      ];
    }
    function box(x, y, w, h) {
      return [
        ['M', x, y],
        ['L', x + w, y],
        ['L', x + w, y + h],
        ['L', x, y + h],
        ['Z']
      ];
    }
    var topArea = H * 0.14;
    var availH = H - topArea - H * 0.06;
    var gap = availH * 0.08;
    var cardH = (availH - 2 * gap) / 3;
    var cardW = W * 0.74;
    var cardX = (W - cardW) / 2;
    var cx = cardX + cardW / 2;
    var rad = Math.min(14, cardH * 0.18);
    var paths = [];
    var children = [];
    var cardYs = [];
    var i, cy;
    for (i = 0; i < 3; i++) {
      cy = topArea + i * (cardH + gap);
      cardYs.push(cy);
      paths.push({ id: 'card' + i, commands: rr(cardX, cy, cardW, cardH, rad) });
      children.push({ type: 'path', pathId: 'card' + i, fill: '#EEF4FD', stroke: { width: 2 } });
      paths.push({ id: 'bar' + i, commands: box(cardX, cy + 6, 6, cardH - 12) });
      children.push({ type: 'path', pathId: 'bar' + i, fill: '#2F6FEB' });
    }
    for (i = 0; i < 2; i++) {
      var y1 = cardYs[i] + cardH + 4;
      var y2 = cardYs[i + 1] - 4;
      paths.push({ id: 'arrow' + i, commands: visualSdk.arrow(cx, y1, cx, y2) });
      children.push({ type: 'path', pathId: 'arrow' + i, fill: '#2F6FEB', stroke: { width: 2 } });
    }
    children.push({
      type: 'label',
      contentId: metrics[0].contentId,
      anchor: { x: cx, y: topArea * 0.4 },
      hAlign: 'center',
      vAlign: 'middle',
      color: '#1F3350'
    });
    for (i = 0; i < 3; i++) {
      children.push({
        type: 'label',
        contentId: metrics[1 + 2 * i].contentId,
        anchor: { x: cx, y: cardYs[i] + cardH * 0.3 },
        hAlign: 'center',
        vAlign: 'middle',
        color: '#1F3350'
      });
      children.push({
        type: 'label',
        contentId: metrics[2 + 2 * i].contentId,
        anchor: { x: cx, y: cardYs[i] + cardH * 0.68 },
        hAlign: 'center',
        vAlign: 'middle',
        color: '#12335E'
      });
    }
    return {
      schemaVersion: 1,
      sceneId: 'one-var-linear-flow',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
